const NewsGrid = ({ noticias }) =&gt; {
  if (!noticias.length) return &lt;p&gt;No hay noticias&lt;/p&gt;;

  return (
    &lt;div className="grid-container"&gt;
      {
        noticias.map((noticia) =&gt; (
          &lt;div key={noticia.id} className="card"&gt;
            &lt;h3&gt;{noticia.titulo}&lt;/h3&gt;
            &lt;p&gt;{noticia.resumen}&lt;/p&gt;
          &lt;/div&gt;
        ))
      }
    &lt;/div&gt;
  );
};

const AlertBoard = () =&gt; {
  const [alertas, setAlertas] = useState([
    { id: 1, text: "Corte de Agua a las 15:00 hrs." }
  ]);

  // Lógica para ELIMINAR elemento del DOM
  const handleCerrar = (idCerrar) =&gt; {
    const filtradas = alertas.filter(a =&gt; a.id !== idCerrar);
    setAlertas(filtradas); // Re-render sin la alerta
  };

  return (
    &lt;div&gt;
      {alertas.map(alerta =&gt; (
        &lt;div key={alerta.id} className="alert-box"&gt;
          &lt;span&gt;{alerta.text}&lt;/span&gt;
          &lt;button onClick={() =&gt; handleCerrar(alerta.id)}&gt;
            X
          &lt;/button&gt;
        &lt;/div&gt;
      ))}
    &lt;/div&gt;
  );
};

const InteractiveWidget = () =&gt; {
  const [hover, setHover] = useState(false);

  // Evento 1: Click
  const handleAceptar = () =&gt; alert("¡Trámite Iniciado!");

  // Evento 2 &amp; 3: Hover in / Hover out
  const handleEntrar = () =&gt; setHover(true);
  const handleSalir = () =&gt; setHover(false);

  return (
    &lt;div 
      onMouseOver={handleEntrar} 
      onMouseOut={handleSalir}
      style={{ background: hover ? "#ccc" : "#fff" }}
    &gt;
      &lt;h4&gt;Trámites Online&lt;/h4&gt;
      &lt;button onClick={handleAceptar}&gt;Ir&lt;/button&gt;
    &lt;/div&gt;
  );
};

const [form, setForm] = useState({
  nombre: '', correo: '', mensaje: ''
});

const handleChange = (e) =&gt; {
  const { name, value } = e.target;
  // Clonar objeto y pisar la propiedad modificada
  setForm({ ...form, [name]: value });
};

return (
  &lt;form&gt;
    &lt;input 
      name="nombre" 
      value={form.nombre} 
      onChange={handleChange} 
    /&gt;
    {/* Igual para correo y mensaje... */}
  &lt;/form&gt;
);

const [error, setError] = useState('');
const [success, setSuccess] = useState(false);

const handleSubmit = (e) =&gt; {
  e.preventDefault(); // Evitar recarga de página

  // 1. Validar Vacíos
  if (!form.nombre || !form.correo || !form.mensaje) {
    setError('Todos los campos son obligatorios');
    return;
  }

  // 2. Validar Correo (Expresión Regular Simple)
  const regex = /^\S+@\S+\.\S+$/;
  if (!regex.test(form.correo)) {
    setError('El formato del correo es inválido');
    return;
  }

  // 3. Flujo Correcto
  setError('');
  setSuccess(true);
  console.log("Enviado al Municipio:", form);
};

return (
  &lt;form onSubmit={handleSubmit}&gt;

    {/* Inputs omitidos */}

    {/* Mensaje de Error Condicional */}
    {error &amp;&amp; (
       &lt;div className="error-box" style={{ color: 'red' }}&gt;
         {error}
       &lt;/div&gt;
    )}

    {/* Mensaje de Éxito Condicional */}
    {success &amp;&amp; (
       &lt;div className="success-box" style={{ color: 'green' }}&gt;
         ¡Solicitud enviada con éxito!
       &lt;/div&gt;
    )}

    &lt;button type="submit"&gt;Enviar Solicitud&lt;/button&gt;
  &lt;/form&gt;
);

const Home = () =&gt; {
  const [loading, setLoading] = useState(true);
  const [datos, setDatos] = useState([]);

  // Se ejecuta UNA SOLA VEZ al renderizar
  useEffect(() =&gt; {
    setTimeout(() =&gt; {
      setDatos([{ id: 1, text: "Día del patrimonio" }]);
      setLoading(false);
    }, 1500);
  }, []); // &lt;-- Array vacío crítico

  if (loading) return &lt;p&gt;Cargando portal...&lt;/p&gt;;
  return &lt;NewsList data={datos} /&gt;;
};

